/// <summary>
/// PaffH 19.09.22
/// sum AmountMST
/// </summary>
/// <returns>NDXAmountMST</returns>
[SysClientCacheDataMethodAttribute]
public display NDXAmountMST NDXsumAmountMST()
{
    CustTransOpenPerDateTmp custTransOpenPerDateTmp = this as CustTransOpenPerDateTmp;
    NDXAmountMST amountMST = (select sum(AmountMST) from custTransOpenPerDateTmp).AmountMST;
    if (amountMST == 0)
    {
        while select * from custTransOpenPerDateTmp
        {
            amountMST += custTransOpenPerDateTmp.AmountMST;
        }
    }
    return amountMST;
}

